-- ------------------------------------------------------------- projects
INSERT INTO projects (id, title, description, long_description, category, featured, technologies, links, date, images, key_features, impact, published, position, updated_at) VALUES ('gig-idea-generation', 'GIG - Greatest Idea Generation', 'Decentralized idea generation platform using blockchain, federated learning, and LLMs to process 127 ideas per second with 100% data integrity.', 'Built a revolutionary decentralized platform for idea generation that combines blockchain technology with federated learning and multiple LLMs (Ollama). The system ensures user privacy through federated learning while maintaining data integrity using SHA-256 blockchain consensus. Implemented FAISS for intelligent idea clustering and semantic search. The platform can process and analyze 127 ideas per second while preserving user ownership and intellectual property rights through immutable blockchain records.', 'AI/ML', true, ARRAY['Python', 'FastAPI', 'Ollama', 'Blockchain', 'Federated Learning', 'FAISS', 'Docker', 'React']::text[], '{"github":"https://github.com/khan09faiz/Idea-Recommendation-model-"}'::jsonb, '2025-09-01', '{}'::text[], ARRAY['Decentralized architecture with blockchain consensus', 'Federated learning for privacy-preserving model training', 'Multi-LLM integration using Ollama', 'FAISS-powered semantic search and clustering', 'Real-time idea processing at 127 ideas/second', 'SHA-256 blockchain for immutable idea records', '100% data integrity guarantee']::text[], '[{"label":"Processing Speed","value":"127 ideas/sec"},{"label":"Data Integrity","value":"100%"},{"label":"User Privacy","value":"Federated"}]'::jsonb, true, 0, now())
