INSERT INTO projects (id, title, description, long_description, category, featured, technologies, links, date, images, key_features, impact, published, position, updated_at) VALUES ('unified-stock-market', 'Unified Stock Market Framework', 'Advanced algorithmic trading framework combining SARIMA-GARCH time series forecasting, FinBERT sentiment analysis, and PPO reinforcement learning for 15.6% returns.', 'Developed a comprehensive algorithmic trading framework that unifies three powerful approaches: SARIMA-GARCH for time series forecasting, FinBERT for financial sentiment analysis, and Proximal Policy Optimization (PPO) for reinforcement learning-based trading decisions. The system achieved 15.6% returns with a Sharpe ratio of 0.89, outperforming traditional buy-and-hold strategy by 3.3%. Implemented robust backtesting, risk management, and real-time market data processing. Containerized with Docker for easy deployment and scalability.', 'AI/ML', true, ARRAY['Python', 'SARIMA', 'GARCH', 'FinBERT', 'PPO', 'Reinforcement Learning', 'Docker', 'Pandas', 'NumPy']::text[], '{"github":"https://github.com/khan09faiz/Unified-stock-market"}'::jsonb, '2025-02-01', '{}'::text[], ARRAY['SARIMA-GARCH time series forecasting', 'FinBERT sentiment analysis from financial news', 'PPO reinforcement learning for trading decisions', 'Comprehensive backtesting framework', 'Risk management with position sizing', 'Real-time market data integration', 'Docker containerization for deployment']::text[], '[{"label":"Total Returns","value":"15.6%"},{"label":"Sharpe Ratio","value":"0.89"},{"label":"Outperformance","value":"+3.3%"}]'::jsonb, true, 1, now())
