INSERT INTO projects (id, title, description, long_description, category, featured, technologies, links, date, images, key_features, impact, published, position, updated_at) VALUES ('blind-cap', 'Blind Cap - Accessibility Wearable', 'YOLOv8-powered wearable device for visually impaired users, achieving 97% detection accuracy with audio and haptic feedback for enhanced navigation.', 'Designed and developed an innovative wearable assistive device for visually impaired individuals using YOLOv8 for real-time object detection and OpenCV for computer vision processing. The system runs on Raspberry Pi 4, processing video at 30 FPS with 97% object detection accuracy. Provides multi-modal feedback through audio descriptions and haptic signals to guide users safely. Field tested with 15 users who reported 60% improvement in navigation confidence. Built with a $50 bill of materials, making it an affordable accessibility solution. Operates completely offline for reliability and privacy.', 'AI/ML', true, ARRAY['Python', 'YOLOv8', 'OpenCV', 'Raspberry Pi', 'TensorFlow Lite', 'Audio Feedback', 'Haptic Feedback']::text[], '{"github":"https://github.com/khan09faiz/blind-cap-object-detection"}'::jsonb, '2024-03-01', '{}'::text[], ARRAY['YOLOv8 real-time object detection at 30 FPS', 'Multi-modal feedback (audio + haptic)', 'Raspberry Pi 4 edge deployment', 'Offline operation for reliability', 'Low-cost design ($50 BOM)', '97% detection accuracy', 'User-tested with 15 visually impaired individuals']::text[], '[{"label":"Detection Accuracy","value":"97%"},{"label":"Navigation Improvement","value":"60%"},{"label":"Users Tested","value":"15"}]'::jsonb, true, 2, now())
